CREATE TYPE "AutomationJobStatus" AS ENUM ('PENDING','PROCESSING','DELIVERED','DEAD');
CREATE TABLE "AutomationRule" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"projectId" TEXT,"name" TEXT NOT NULL,"trigger" JSONB NOT NULL,"conditions" JSONB NOT NULL,"actions" JSONB NOT NULL,"permissions" TEXT[],"enabled" BOOLEAN NOT NULL DEFAULT true,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AutomationRule_pkey" PRIMARY KEY("id"));
CREATE TABLE "AutomationJob" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"ruleId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"event" TEXT NOT NULL,"payload" JSONB NOT NULL,"correlationId" TEXT NOT NULL,"depth" INTEGER NOT NULL DEFAULT 0,"status" "AutomationJobStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AutomationJob_pkey" PRIMARY KEY("id"));
CREATE TABLE "AutomationExecution" ("id" TEXT NOT NULL,"workspaceId" TEXT NOT NULL,"ruleId" TEXT NOT NULL,"jobId" TEXT NOT NULL,"correlationId" TEXT NOT NULL,"input" JSONB NOT NULL,"result" JSONB NOT NULL,"durationMs" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AutomationExecution_pkey" PRIMARY KEY("id"));
CREATE INDEX "AutomationRule_workspaceId_projectId_enabled_idx" ON "AutomationRule"("workspaceId","projectId","enabled"); CREATE UNIQUE INDEX "AutomationJob_ruleId_eventId_key" ON "AutomationJob"("ruleId","eventId"); CREATE INDEX "AutomationJob_status_availableAt_idx" ON "AutomationJob"("status","availableAt"); CREATE UNIQUE INDEX "AutomationExecution_jobId_key" ON "AutomationExecution"("jobId"); CREATE INDEX "AutomationExecution_workspaceId_createdAt_idx" ON "AutomationExecution"("workspaceId","createdAt"); CREATE INDEX "AutomationExecution_ruleId_createdAt_idx" ON "AutomationExecution"("ruleId","createdAt");
ALTER TABLE "AutomationRule" ADD CONSTRAINT "AutomationRule_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AutomationRule" ADD CONSTRAINT "AutomationRule_projectId_fkey" FOREIGN KEY("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AutomationJob" ADD CONSTRAINT "AutomationJob_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AutomationJob" ADD CONSTRAINT "AutomationJob_ruleId_fkey" FOREIGN KEY("ruleId") REFERENCES "AutomationRule"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AutomationExecution" ADD CONSTRAINT "AutomationExecution_workspaceId_fkey" FOREIGN KEY("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AutomationExecution" ADD CONSTRAINT "AutomationExecution_ruleId_fkey" FOREIGN KEY("ruleId") REFERENCES "AutomationRule"("id") ON DELETE CASCADE ON UPDATE CASCADE;
